import logging
import re
import time
from operator import add, sub

from taf.hw.rf_attenuator.utils.telnet import TelnetClient
from taf.hw.rf_attenuator.attenuator_class import Attenuator
from taf.hw.rf_attenuator.exceptions import AttenuationReadError


def _roundup(number, ndigits):
    precision = 10 ** (-1 * ndigits)
    if number % (0.5 * precision) == 0 and number % precision != 0:
        operator = add if number > 0 else sub
        number = operator(number, 0.1 * precision)
    return round(number, ndigits)


class RadioRack(Attenuator):
    MAX_SUPPORTED_ATTENUATION = 110
    MIN_SUPPORTED_ATTENUATION = 0

    def __init__(self, ip, port=50000, min_attenuation=None, max_attenuation=None):
        super(RadioRack, self).__init__()
        self.ip = ip
        self.port = port
        self.conn = None
        self.telnet = TelnetClient()
        self.is_connected = False
        self.min_attenuation = self._validate_min_attenuation(min_attenuation, self.MIN_SUPPORTED_ATTENUATION)
        self.max_attenuation = self._validate_max_attenuation(max_attenuation, self.MAX_SUPPORTED_ATTENUATION)

    def connect(self, **kwargs):
        """
        Establish connection with attenuation controller
        allowing to change attenuation on specific RF-port of that device
        """
        if not self.is_connected:
            self.telnet.connect(self.ip, self.port)
            self.is_connected = True
            logging.info('Connection to RadioRack rf_attenuator established.')

    def disconnect(self, **kwargs):
        """
        Release connection with attenuation controller
        """
        if self.is_connected:
            self.telnet.close_connection()
            self.is_connected = False
        else:
            logging.warning('Connection to RadioRack is not established.')

    def _set_single_port_decibel_attenuation(self, rf_port_address, attenuation_value):
        attenuation_value = int(_roundup(attenuation_value, 1))
        cmd = "ATT {} {}".format(rf_port_address, attenuation_value)
        self._write_and_read(cmd)
        logging.info('Port ID {} value set to {} dB.'.format(rf_port_address, attenuation_value))

    def _write_and_read(self, cmd):
        resp = self.telnet.read_command_output(cmd, read_method='until')
        logging.debug('The response of Sending command: {}'.format(resp))
        return resp

    def read_port_attenuation(self, port):
        time.sleep(0.5)
        att_output = self.telnet.read_command_output('ATT', read_method='until')
        logging.debug('Attenuator state: {}'.format(att_output))
        pattern = r'ATT\s{1,}' + str(port) + r'\s{1,}(\d{1,})'
        re_out = re.search(pattern, att_output)
        if re_out:
            logging.debug(re_out.groups()[0])
            value_read = re_out.groups()[0]
            logging.debug('Port ID {} state = {}'.format(str(port), value_read))
            return int(value_read)
        else:
            raise AttenuationReadError(
                "Failed to read attenuation of port {}. Make sure the port exists. "
                "If it does - connection limit might be exceeded. Try to stop the "
                "sessions that are currently running on the attenuator.".format(port)
            )
